INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_5b30a73cc5dd1e', 'subj_phys', 'wave-speed', 'Wave speed and the Doppler effect', 'v = f\lambda, \quad T = \frac{1}{f}, \qquad f'' = f\,\frac{v \pm v_o}{v \mp v_s}', 'Wave speed equals frequency times wavelength. Doppler: use the top signs when observer and source move toward each other.', '[{"symbol":"f","meaning":"frequency","unit":"Hz"},{"symbol":"\\lambda","meaning":"wavelength","unit":"m"},{"symbol":"v_o, v_s","meaning":"observer and source speeds","unit":"m/s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_aa3afdee332a10', 'subj_phys', 'optics-equations', 'Snell''s law and the thin lens equation', 'n_1\sin\theta_1 = n_2\sin\theta_2, \quad \tfrac{1}{f} = \tfrac{1}{d_o} + \tfrac{1}{d_i}, \quad m = -\tfrac{d_i}{d_o}', 'Refraction at a boundary, and image location and magnification for thin lenses and spherical mirrors.', '[{"symbol":"n","meaning":"index of refraction"},{"symbol":"f","meaning":"focal length","unit":"m"},{"symbol":"d_o, d_i","meaning":"object and image distances","unit":"m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_427b25957020b7', 'subj_phys', 'coulombs-law', 'Coulomb''s law and electric field', 'F = \frac{k|q_1q_2|}{r^2}, \qquad E = \frac{F}{q} = \frac{k|q|}{r^2}, \qquad k = 8.99 \times 10^9\ \text{N·m}^2/\text{C}^2', 'The force between point charges and the field of a point charge.', '[{"symbol":"q","meaning":"charge","unit":"C"},{"symbol":"r","meaning":"distance","unit":"m"},{"symbol":"E","meaning":"electric field","unit":"N/C"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1b1594bf793b96', 'subj_phys', 'magnetism-induction', 'Magnetic force and induction', 'F = qvB\sin\theta, \quad F = ILB\sin\theta, \quad \Phi = BA\cos\theta, \quad \varepsilon = -N\frac{\Delta\Phi}{\Delta t}', 'Magnetic force on a moving charge and on a current-carrying wire, magnetic flux, and Faraday''s law of induction.', '[{"symbol":"B","meaning":"magnetic field","unit":"T"},{"symbol":"\\Phi","meaning":"magnetic flux","unit":"Wb"},{"symbol":"\\varepsilon","meaning":"induced emf","unit":"V"}]', 'published');

-- Lesson: coulombs-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_427b25957020b7', 'coulombs-law', 'Electric charge and Coulomb''s law', 'Describe charge, conductors, insulators and charging by contact and induction, then compute electric forces with Coulomb''s law.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e70e3e26742aa6', 'les_427b25957020b7', 1, 'Explain charge conservation and quantization (e = 1.6 × 10⁻¹⁹ C).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d1b25e3303260', 'les_427b25957020b7', 2, 'Compare conductors and insulators, and charging by friction, contact and induction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_77d5f5463b9e64', 'les_427b25957020b7', 3, 'Use F = k|q₁q₂|/r² and the inverse-square law.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e70e3e26742aa6', 'les_427b25957020b7', 'learn', 1, 'definition', '{"term":"Charge","body":"Charge comes in two kinds, positive and negative: like charges repel and opposite charges attract. Charge is conserved and comes in multiples of $e = 1.6 \\times 10^{-19}$ C. Objects charge by gaining or losing electrons. In conductors (metals) electrons move freely; in insulators (rubber, glass) they don''t."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d1b25e3303260', 'les_427b25957020b7', 'learn', 2, 'definition', '{"term":"Coulomb''s law","body":"$F = k\\,\\frac{|q_1 q_2|}{r^2}$ with $k = 8.99 \\times 10^9\\ \\text{N·m}^2/\\text{C}^2$. Doubling the distance cuts the force to one quarter."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_77d5f5463b9e64', 'les_427b25957020b7', 'learn', 3, 'worked_example', '{"title":"Charges of +2 μC and −2 μC sit 4 m apart","steps":[{"latex":"F = \\tfrac{(8.99\\times10^9)(2\\times10^{-6})(2\\times10^{-6})}{4^2}","explanation":""},{"latex":"F \\approx 2.25 \\times 10^{-3}\\ \\text{N}","explanation":"Attractive, since the signs are opposite."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97bf8fe4ef2734', 'les_427b25957020b7', 'experiment', 4, 'activity', '{"activity":"electric-field","title":"Two charges","params":{"q1":2,"q2":-2,"separation":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b69fce4653963f', 'les_427b25957020b7', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Read the force between the charges, then double the separation from 4 m to 8 m: the force drops to one quarter. Flip one charge''s sign to see the field change from attracting to repelling."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5beb7f6c2de65', 'les_427b25957020b7', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Static cling, lightning, photocopiers and laser printers (toner sticks to charged regions) and paint sprayers that charge droplets for an even coat."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e70e3e26742aa6', 'les_427b25957020b7', 1, 'practice', 'numeric', 2, 'Two +1 μC charges are 0.1 m apart. Find the force between them, in newtons.', '{"answer":0.899,"tolerance":0.002,"unit":"N"}', '[]', '$\frac{8.99\times10^9 \cdot 10^{-12}}{0.01}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d1b25e3303260', 'les_427b25957020b7', 2, 'practice', 'multiple_choice', 2, 'The distance between two charges triples. The force becomes…', '{"choices":["3 times larger","1/3 as large","1/9 as large","9 times larger"],"answer":2}', '[]', 'Inverse square: $\frac{1}{3^2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_77d5f5463b9e64', 'les_427b25957020b7', 3, 'practice', 'numeric', 2, 'How many electrons must be removed to give an object a charge of +3.2 × 10⁻¹⁸ C?', '{"answer":20,"unit":"electrons"}', '[]', '$\frac{3.2\times10^{-18}}{1.6\times10^{-19}} = 20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97bf8fe4ef2734', 'les_427b25957020b7', 4, 'review', 'multiple_choice', 3, 'A charged balloon sticks to a neutral wall because…', '{"choices":["the wall is charged","it induces a separation of charge in the wall''s surface","gravity","magnetism"],"answer":1}', '[]', 'Opposite charges are pulled slightly closer than like charges (polarization).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1065b901bcd94e', 'subj_phys', 'electrostatics', 'Electrostatics', 'Forces and fields produced by electric charges at rest.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_427b25957020b7', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_427b25957020b7', (SELECT id FROM formulas WHERE slug = 'coulombs-law'), 1);

-- Lesson: electric-fields
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_deae875542bdc2', 'electric-fields', 'Electric fields', 'Define the electric field as force per unit charge, compute fields of point charges, add fields as vectors and read field-line diagrams.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b737fe10f4237e', 'les_deae875542bdc2', 1, 'Define E = F/q and give its units (N/C).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_650d5688c1ea02', 'les_deae875542bdc2', 2, 'Compute the field of a point charge, E = kq/r².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9e29787d5a99b', 'les_deae875542bdc2', 3, 'Sketch and interpret field lines for one and two charges.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b737fe10f4237e', 'les_deae875542bdc2', 'learn', 1, 'definition', '{"term":"Electric field","body":"The field at a point is the force per unit positive test charge: $\\vec{E} = \\frac{\\vec{F}}{q}$, in N/C. For a point charge, $E = \\frac{k|q|}{r^2}$, pointing away from positive charges and toward negative ones. Fields from several charges add as vectors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_650d5688c1ea02', 'les_deae875542bdc2', 'learn', 2, 'definition', '{"term":"Field lines","body":"Field lines start on positive charges and end on negative ones. They never cross, and they bunch together where the field is strong."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9e29787d5a99b', 'les_deae875542bdc2', 'learn', 3, 'worked_example', '{"title":"Field 0.5 m from a +3 μC charge","steps":[{"latex":"E = \\tfrac{(8.99\\times10^9)(3\\times10^{-6})}{0.5^2}","explanation":""},{"latex":"E \\approx 1.08 \\times 10^5\\ \\text{N/C}","explanation":"Pointing away from the charge."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0006d4b96da0f9', 'les_deae875542bdc2', 'learn', 4, 'worked_example', '{"title":"Force on an electron in a 1000 N/C field","steps":[{"latex":"F = qE = (1.6\\times10^{-19})(1000)","explanation":""},{"latex":"F = 1.6 \\times 10^{-16}\\ \\text{N}","explanation":"Opposite the field, since the charge is negative."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c9e8e1da7a2b9a', 'les_deae875542bdc2', 'experiment', 5, 'activity', '{"activity":"electric-field","title":"Probe the field","params":{"q1":2,"q2":-2,"separation":4,"px":0,"py":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f41cae91e0f4f6', 'les_deae875542bdc2', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Drag the probe between the charges and then far away: the arrows fade as the field weakens. Make both charges positive and find the point midway between them where the field is zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e3e4e7a3aaa0f', 'les_deae875542bdc2', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Old CRT TVs and particle accelerators steer charged beams with fields, and a car''s metal body shields you in a lightning storm because the field inside a conductor is zero."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b737fe10f4237e', 'les_deae875542bdc2', 1, 'practice', 'numeric', 2, 'A 2 μC charge feels a 0.01 N force. Find the field strength, in N/C.', '{"answer":5000,"unit":"N/C"}', '[]', '$\frac{0.01}{2\times10^{-6}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_650d5688c1ea02', 'les_deae875542bdc2', 2, 'practice', 'numeric', 2, 'Find the field 0.3 m from a 1 μC charge, to the nearest 10 N/C.', '{"answer":99900,"tolerance":50,"unit":"N/C"}', '[]', '$\frac{8.99\times10^9\cdot10^{-6}}{0.09} \approx 9.99\times10^4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9e29787d5a99b', 'les_deae875542bdc2', 3, 'practice', 'multiple_choice', 2, 'A proton is released in a uniform field pointing east. It accelerates…', '{"choices":["east","west","north","not at all"],"answer":0}', '[]', 'Positive charges are pushed along the field.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0006d4b96da0f9', 'les_deae875542bdc2', 4, 'review', 'multiple_choice', 3, 'Two equal positive charges. At the midpoint between them, the field is…', '{"choices":["twice one charge''s field","zero","pointing toward one charge","infinite"],"answer":1}', '[]', 'Equal and opposite contributions cancel.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1065b901bcd94e', 'subj_phys', 'electrostatics', 'Electrostatics', 'Forces and fields produced by electric charges at rest.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_deae875542bdc2', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_deae875542bdc2', (SELECT id FROM formulas WHERE slug = 'coulombs-law'), 1);

-- Lesson: electric-power-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ab42cf75803231', 'electric-power-energy', 'Electric power and energy', 'Compute electric power with P = IV, I²R and V²/R, convert energy to kilowatt-hours and estimate electricity costs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8a2938ab79a015', 'les_ab42cf75803231', 1, 'Use P = IV, P = I²R and P = V²/R.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_673eff6d73c876', 'les_ab42cf75803231', 2, 'Convert between joules and kilowatt-hours.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4fbbd927b93afc', 'les_ab42cf75803231', 3, 'Estimate the cost of running household devices.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a2938ab79a015', 'les_ab42cf75803231', 'learn', 1, 'definition', '{"term":"Electric power","body":"Power is the rate of energy transfer: $P = IV$. Combining with Ohm''s law gives $P = I^2R = \\frac{V^2}{R}$. Power is measured in watts (1 W = 1 J/s)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_673eff6d73c876', 'les_ab42cf75803231', 'learn', 2, 'definition', '{"term":"Kilowatt-hours","body":"Utilities bill energy in kilowatt-hours: $1\\ \\text{kWh} = 1000\\ \\text{W} \\times 3600\\ \\text{s} = 3.6 \\times 10^6\\ \\text{J}$. Energy = power × time."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fbbd927b93afc', 'les_ab42cf75803231', 'learn', 3, 'worked_example', '{"title":"A 60 W bulb on a 120 V circuit","steps":[{"latex":"I = \\tfrac{P}{V} = \\tfrac{60}{120} = 0.5\\ \\text{A}","explanation":""},{"latex":"R = \\tfrac{V}{I} = 240\\ \\Omega","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9f0eb749d890f', 'les_ab42cf75803231', 'learn', 4, 'worked_example', '{"title":"Monthly cost: the bulb runs 5 h/day for 30 days at 15 cents per kWh","steps":[{"latex":"E = 0.060\\ \\text{kW} \\times 150\\ \\text{h} = 9\\ \\text{kWh}","explanation":""},{"latex":"\\text{cost} = 9 \\times 0.15 = \\$1.35","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e8bfc60798958f', 'les_ab42cf75803231', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"An LED bulb gives the same light as a 60 W incandescent at about 9 W, so swapping cuts that cost by 85%. Circuit breakers trip when total current (total power ÷ 120 V) exceeds about 15–20 A."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a2938ab79a015', 'les_ab42cf75803231', 1, 'practice', 'numeric', 1, 'A toaster draws 10 A at 120 V. Find its power.', '{"answer":1200,"unit":"W"}', '[]', '$10 \times 120$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_673eff6d73c876', 'les_ab42cf75803231', 2, 'practice', 'numeric', 2, 'A 2 Ω heater carries 5 A. Find its power.', '{"answer":50,"unit":"W"}', '[]', '$I^2R = 25 \times 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fbbd927b93afc', 'les_ab42cf75803231', 3, 'practice', 'numeric', 2, 'A 1500 W space heater runs 4 hours. How many kWh does it use?', '{"answer":6,"unit":"kWh"}', '[]', '$1.5 \times 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9f0eb749d890f', 'les_ab42cf75803231', 4, 'review', 'numeric', 3, 'At 12 cents per kWh, what does running a 100 W TV for 3 hours a day for 30 days cost, in dollars?', '{"answer":1.08,"tolerance":0.01,"unit":"dollars"}', '[]', '$0.1 \times 90 = 9$ kWh, then $9 \times 0.12$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ee5482bde8c281', 'subj_phys', 'circuits', 'Electric circuits', 'Current, voltage and resistance in series and parallel circuits.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ab42cf75803231', (SELECT id FROM concepts WHERE slug = 'circuits'));

-- Lesson: electromagnetic-induction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_416d2b557628d4', 'electromagnetic-induction', 'Electromagnetic induction', 'Use magnetic flux and Faraday''s law to find induced voltages, apply Lenz''s law, and explain generators and transformers.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e8221b9551895', 'les_416d2b557628d4', 1, 'Define magnetic flux Φ = BA cos θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_588075b32a6f5d', 'les_416d2b557628d4', 2, 'Apply Faraday''s law, ε = −N ΔΦ/Δt, and Lenz''s law.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e70eb2bac134e1', 'les_416d2b557628d4', 3, 'Explain generators and use the transformer ratio Vs/Vp = Ns/Np.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e8221b9551895', 'les_416d2b557628d4', 'learn', 1, 'definition', '{"term":"Flux and Faraday''s law","body":"Magnetic flux through a loop is $\\Phi = BA\\cos\\theta$ (webers). A changing flux induces a voltage (emf): $\\varepsilon = -N\\frac{\\Delta\\Phi}{\\Delta t}$. Change B, the area or the angle, and you get a voltage."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_588075b32a6f5d', 'les_416d2b557628d4', 'learn', 2, 'definition', '{"term":"Lenz''s law","body":"The induced current flows so its own field opposes the change in flux. That''s the minus sign, and it''s energy conservation: you must do work to push a magnet into a coil."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e70eb2bac134e1', 'les_416d2b557628d4', 'learn', 3, 'worked_example', '{"title":"A 100-turn coil of area 0.01 m²; B rises from 0 to 0.5 T in 0.1 s","steps":[{"latex":"\\Delta\\Phi = (0.5)(0.01) = 0.005\\ \\text{Wb}","explanation":""},{"latex":"|\\varepsilon| = 100\\cdot\\tfrac{0.005}{0.1} = 5\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c7746eaa04b3b', 'les_416d2b557628d4', 'learn', 4, 'definition', '{"term":"Generators and transformers","body":"A generator spins a coil in a field, so the flux changes continuously and produces alternating current. A transformer links two coils with a shared iron core: $\\frac{V_s}{V_p} = \\frac{N_s}{N_p}$. It works only with AC, since a steady current gives no changing flux."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71a377d3731331', 'les_416d2b557628d4', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Power plants generate electricity by induction; grids step voltage up for long-distance lines (less current, less $I^2R$ loss), then down for homes. Wireless chargers and induction stoves use the same principle."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e8221b9551895', 'les_416d2b557628d4', 1, 'practice', 'numeric', 2, 'A transformer has 500 primary turns and 50 secondary turns, with 120 V on the primary. Find the secondary voltage.', '{"answer":12,"unit":"V"}', '[]', '$120 \cdot \frac{50}{500}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_588075b32a6f5d', 'les_416d2b557628d4', 2, 'practice', 'numeric', 2, 'A 20-turn coil''s flux drops from 0.03 Wb to 0 in 0.2 s. Find the size of the induced emf.', '{"answer":3,"unit":"V"}', '[]', '$20 \cdot \frac{0.03}{0.2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e70eb2bac134e1', 'les_416d2b557628d4', 3, 'practice', 'multiple_choice', 2, 'A magnet sits at rest inside a coil. The induced current is…', '{"choices":["large","zero","alternating","steady"],"answer":1}', '[]', 'No change in flux, no emf.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c7746eaa04b3b', 'les_416d2b557628d4', 4, 'review', 'multiple_choice', 3, 'Why are long-distance power lines run at very high voltage?', '{"choices":["Electrons move faster","For the same power, lower current means less I²R loss","High voltage is safer","Transformers need it"],"answer":1}', '[]', '$P = IV$: raise V, lower I, and losses drop as $I^2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cf68efd57405e2', 'subj_phys', 'magnetism', 'Magnetism', 'Magnetic fields from magnets and currents, magnetic forces and electromagnetic induction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_416d2b557628d4', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_416d2b557628d4', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: electromagnetic-spectrum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_810871f281881b', 'electromagnetic-spectrum', 'The electromagnetic spectrum', 'Describe light as an electromagnetic wave traveling at c, order the spectrum from radio to gamma rays, and use c = fλ.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_40ec9e0dfa8f4e', 'les_810871f281881b', 1, 'Order the bands of the electromagnetic spectrum by wavelength and frequency.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_594b249aad55db', 'les_810871f281881b', 2, 'Use c = fλ with c = 3.00 × 10⁸ m/s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_66a40958d262db', 'les_810871f281881b', 3, 'Connect higher frequency to higher photon energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_40ec9e0dfa8f4e', 'les_810871f281881b', 'learn', 1, 'definition', '{"term":"EM waves","body":"Light is a transverse wave of electric and magnetic fields that needs no medium; in vacuum all EM waves travel at $c = 3.00 \\times 10^8$ m/s. From long wavelength to short: radio, microwaves, infrared, visible (about 700 nm red to 400 nm violet), ultraviolet, X-rays, gamma rays."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_594b249aad55db', 'les_810871f281881b', 'learn', 2, 'worked_example', '{"title":"Wavelength of a 100 MHz FM radio station","steps":[{"latex":"\\lambda = \\tfrac{c}{f} = \\tfrac{3 \\times 10^8}{1 \\times 10^8} = 3\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_66a40958d262db', 'les_810871f281881b', 'learn', 3, 'worked_example', '{"title":"Frequency of green light, λ = 550 nm","steps":[{"latex":"f = \\tfrac{3 \\times 10^8}{5.5 \\times 10^{-7}} \\approx 5.5 \\times 10^{14}\\ \\text{Hz}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1e1c459b68993', 'les_810871f281881b', 'learn', 4, 'callout', '{"tone":"note","title":"Energy","body":"Each photon carries energy $E = hf$. Higher-frequency light (UV, X-rays) carries more energy per photon, which is why it can damage cells while radio waves can''t."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e403bf943b4a84', 'les_810871f281881b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Wi-Fi (2.4 and 5 GHz), microwave ovens, TV remotes (infrared), medical X-rays and sunscreen (UV protection) each use a different band."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_40ec9e0dfa8f4e', 'les_810871f281881b', 1, 'practice', 'numeric', 1, 'Find the wavelength of 2.4 GHz Wi-Fi, in meters.', '{"answer":0.125,"tolerance":0.001,"unit":"m"}', '[]', '$\frac{3 \times 10^8}{2.4 \times 10^9}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_594b249aad55db', 'les_810871f281881b', 2, 'practice', 'multiple_choice', 2, 'Which has the highest frequency?', '{"choices":["Radio","Infrared","Ultraviolet","Microwave"],"answer":2}', '[]', 'Shortest wavelength of the four.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_66a40958d262db', 'les_810871f281881b', 3, 'practice', 'multiple_choice', 2, 'In a vacuum, red light and blue light have the same…', '{"choices":["frequency","wavelength","speed","photon energy"],"answer":2}', '[]', 'All EM waves travel at c.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d1e1c459b68993', 'les_810871f281881b', 4, 'review', 'numeric', 3, 'Light takes about 500 s to travel from the Sun to Earth. Estimate the distance, in units of $10^{11}$ m.', '{"answer":1.5,"tolerance":0.01}', '[]', '$3 \times 10^8 \times 500 = 1.5 \times 10^{11}$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f56490e50b0e63', 'subj_phys', 'waves', 'Waves', 'Disturbances that carry energy through a medium or through space without carrying matter along.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_810871f281881b', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_810871f281881b', (SELECT id FROM formulas WHERE slug = 'wave-speed'), 1);

-- Lesson: magnetic-fields-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_055336d2463e9f', 'magnetic-fields-forces', 'Magnetic fields and forces', 'Describe magnetic fields of magnets and currents, and compute forces on moving charges and current-carrying wires with right-hand rules.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_71ec924b46eaeb', 'les_055336d2463e9f', 1, 'Describe magnetic poles and field lines.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d7d9410cb809b8', 'les_055336d2463e9f', 2, 'Find the field around a long straight wire, B = μ₀I/(2πr).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3da0f5d9a13e76', 'les_055336d2463e9f', 3, 'Use F = qvB sin θ and F = ILB sin θ with the right-hand rule.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71ec924b46eaeb', 'les_055336d2463e9f', 'learn', 1, 'definition', '{"term":"Magnetic fields","body":"Magnets have north and south poles; like poles repel. Field lines leave north and enter south, and poles always come in pairs. Moving charges, meaning currents, create magnetic fields: around a long straight wire, $B = \\frac{\\mu_0 I}{2\\pi r}$ with $\\mu_0 = 4\\pi\\times10^{-7}$ T·m/A, circling the wire (right thumb along the current, fingers curl with B)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7d9410cb809b8', 'les_055336d2463e9f', 'learn', 2, 'definition', '{"term":"Magnetic force","body":"A charge moving through a field feels $F = qvB\\sin\\theta$, perpendicular to both $\\vec{v}$ and $\\vec{B}$. On a wire, $F = ILB\\sin\\theta$. Point your fingers along $\\vec{v}$ (or I), curl them toward $\\vec{B}$, and your thumb gives the force on a positive charge."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3da0f5d9a13e76', 'les_055336d2463e9f', 'learn', 3, 'worked_example', '{"title":"Field 2 cm from a wire carrying 10 A","steps":[{"latex":"B = \\tfrac{(4\\pi\\times10^{-7})(10)}{2\\pi(0.02)} = 1\\times10^{-4}\\ \\text{T}","explanation":"About twice Earth''s field."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ee35f12aa19e6', 'les_055336d2463e9f', 'learn', 4, 'worked_example', '{"title":"A 0.2 m wire carrying 3 A at right angles to a 0.4 T field","steps":[{"latex":"F = ILB = (3)(0.2)(0.4) = 0.24\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_508276a00d0e55', 'les_055336d2463e9f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electric motors spin because of forces on current loops; MRI machines use fields of about 1.5–3 T; Earth''s field steers solar wind particles into the auroras."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_71ec924b46eaeb', 'les_055336d2463e9f', 1, 'practice', 'numeric', 2, 'A proton ($q = 1.6\times10^{-19}$ C) moves at $1\times10^6$ m/s perpendicular to a 1 T field. Find the force, in units of $10^{-13}$ N.', '{"answer":1.6,"tolerance":0.01}', '[]', '$qvB = 1.6\times10^{-13}$ N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d7d9410cb809b8', 'les_055336d2463e9f', 2, 'practice', 'multiple_choice', 2, 'A charge moves parallel to a magnetic field. The magnetic force on it is…', '{"choices":["maximum","zero","along the field","opposite the field"],"answer":1}', '[]', '$\sin 0° = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3da0f5d9a13e76', 'les_055336d2463e9f', 3, 'practice', 'numeric', 2, 'Find the field 0.05 m from a wire carrying 5 A, in units of $10^{-5}$ T.', '{"answer":2,"tolerance":0.01}', '[]', '$\frac{2\times10^{-7}\cdot 5}{0.05} = 2\times10^{-5}$ T.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ee35f12aa19e6', 'les_055336d2463e9f', 4, 'review', 'multiple_choice', 3, 'Why can''t a magnetic force change a charged particle''s speed?', '{"choices":["It''s too weak","It''s always perpendicular to the velocity, so it does no work","Charges have no mass","It only acts on magnets"],"answer":1}', '[]', 'It only turns the particle, which is why charges circle in a field.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cf68efd57405e2', 'subj_phys', 'magnetism', 'Magnetism', 'Magnetic fields from magnets and currents, magnetic forces and electromagnetic induction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_055336d2463e9f', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_055336d2463e9f', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: ohms-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_66bdfe1d6261ba', 'ohms-law', 'Current, voltage and resistance (Ohm''s law)', 'Define current, voltage and resistance, use V = IR, and understand what sets a wire''s resistance.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3c62b76cecf801', 'les_66bdfe1d6261ba', 1, 'Define current (A), potential difference (V) and resistance (Ω).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1f8f5934ea6a55', 'les_66bdfe1d6261ba', 2, 'Apply Ohm''s law V = IR.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_351a439b1f73dd', 'les_66bdfe1d6261ba', 3, 'Explain how length, area and material affect resistance (R = ρL/A).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c62b76cecf801', 'les_66bdfe1d6261ba', 'learn', 1, 'definition', '{"term":"Current and voltage","body":"Current is the rate charge flows: $I = \\frac{\\Delta q}{\\Delta t}$, in amperes (1 A = 1 C/s). Voltage (potential difference) is the energy per unit charge a source provides: 1 V = 1 J/C."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f8f5934ea6a55', 'les_66bdfe1d6261ba', 'learn', 2, 'definition', '{"term":"Resistance","body":"Resistance opposes current. For many materials (ohmic conductors), $V = IR$. A wire''s resistance is $R = \\frac{\\rho L}{A}$: longer and thinner wires resist more, and copper ($\\rho$ small) resists less than nichrome."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_351a439b1f73dd', 'les_66bdfe1d6261ba', 'learn', 3, 'worked_example', '{"title":"A 12 V battery drives current through a 4 Ω resistor","steps":[{"latex":"I = \\tfrac{V}{R} = \\tfrac{12}{4} = 3\\ \\text{A}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90e8e32308bba1', 'les_66bdfe1d6261ba', 'experiment', 4, 'activity', '{"activity":"circuit-builder","title":"Vary the voltage and resistance"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1e78686a7430f', 'les_66bdfe1d6261ba', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Double the battery voltage and the current doubles; double a resistor and the current halves. That''s Ohm''s law."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_014210ea4e9e5d', 'les_66bdfe1d6261ba', 'learn', 6, 'callout', '{"tone":"warning","title":"Safety","body":"Current, not voltage alone, does damage in the body; as little as 0.1 A across the heart can be fatal. Wet skin lowers your resistance, which is why water and outlets don''t mix."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c62b76cecf801', 'les_66bdfe1d6261ba', 1, 'practice', 'numeric', 1, 'A 9 V battery and a 3 Ω resistor. Find the current.', '{"answer":3,"unit":"A"}', '[]', '$\frac{9}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f8f5934ea6a55', 'les_66bdfe1d6261ba', 2, 'practice', 'numeric', 2, 'A 2 A current flows through a 6 Ω resistor. Find the voltage across it.', '{"answer":12,"unit":"V"}', '[]', '$2 \times 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_351a439b1f73dd', 'les_66bdfe1d6261ba', 3, 'practice', 'numeric', 2, 'A 0.5 A current runs for 60 s. How much charge passes, in coulombs?', '{"answer":30,"unit":"C"}', '[]', '$q = It$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90e8e32308bba1', 'les_66bdfe1d6261ba', 4, 'review', 'multiple_choice', 3, 'A wire is replaced by one twice as long and of the same thickness and material. Its resistance…', '{"choices":["halves","doubles","quadruples","stays the same"],"answer":1}', '[]', '$R \propto L$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ee5482bde8c281', 'subj_phys', 'circuits', 'Electric circuits', 'Current, voltage and resistance in series and parallel circuits.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_66bdfe1d6261ba', (SELECT id FROM concepts WHERE slug = 'circuits'));

-- Lesson: properties-of-waves
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0446e250e3077c', 'properties-of-waves', 'Properties of waves', 'Describe mechanical waves as transverse or longitudinal, name amplitude, wavelength, frequency and period, and use v = fλ.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0495a70c5769b6', 'les_0446e250e3077c', 1, 'Distinguish transverse and longitudinal waves.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42dfb7f5690a24', 'les_0446e250e3077c', 2, 'Identify amplitude, wavelength, frequency and period.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_150e72040c868f', 'les_0446e250e3077c', 3, 'Use v = fλ and T = 1/f.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0495a70c5769b6', 'les_0446e250e3077c', 'learn', 1, 'definition', '{"term":"Waves","body":"A wave carries energy without carrying matter along. In a transverse wave (a string, light) the medium moves perpendicular to the wave''s travel; in a longitudinal wave (sound) it moves back and forth along it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42dfb7f5690a24', 'les_0446e250e3077c', 'learn', 2, 'definition', '{"term":"Describing a wave","body":"Amplitude $A$: maximum displacement. Wavelength $\\lambda$: distance between neighboring crests. Frequency $f$: waves per second (Hz). Period $T = \\frac{1}{f}$. Speed $v = f\\lambda$, set by the medium."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_150e72040c868f', 'les_0446e250e3077c', 'learn', 3, 'worked_example', '{"title":"A 440 Hz tuning fork in air (v = 340 m/s)","steps":[{"latex":"\\lambda = \\tfrac{v}{f} = \\tfrac{340}{440} \\approx 0.77\\ \\text{m}","explanation":""},{"latex":"T = \\tfrac{1}{440} \\approx 0.0023\\ \\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43833a802ea214', 'les_0446e250e3077c', 'experiment', 4, 'activity', '{"activity":"waves","title":"Follow a crest","params":{"mode":"travel","wavelength":2,"frequency":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa3c783e11e472', 'les_0446e250e3077c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Move the time slider and track the orange crest: it moves $\\lambda$ in one period, so its speed is $\\frac{\\lambda}{T} = f\\lambda$. Double the frequency: the wavelength stays put in the sim, so the speed doubles. In a real medium the speed stays fixed and the wavelength halves."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bc6b603179929', 'les_0446e250e3077c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ultrasound imaging, earthquake detection (P-waves are longitudinal, S-waves transverse) and every musical instrument rely on these properties."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0495a70c5769b6', 'les_0446e250e3077c', 1, 'practice', 'numeric', 1, 'A wave has frequency 5 Hz and wavelength 2 m. Find its speed.', '{"answer":10,"unit":"m/s"}', '[]', '$5 \times 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42dfb7f5690a24', 'les_0446e250e3077c', 2, 'practice', 'numeric', 1, 'Find the period of a 4 Hz wave.', '{"answer":0.25,"tolerance":0.001,"unit":"s"}', '[]', '$\frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_150e72040c868f', 'les_0446e250e3077c', 3, 'practice', 'multiple_choice', 2, 'Sound is a…', '{"choices":["transverse wave","longitudinal wave","electromagnetic wave","standing wave only"],"answer":1}', '[]', 'Air compresses and expands along the direction of travel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43833a802ea214', 'les_0446e250e3077c', 4, 'review', 'multiple_choice', 3, 'A wave moves from one medium into another and slows down. Its frequency…', '{"choices":["increases","decreases","stays the same","becomes zero"],"answer":2}', '[]', 'Frequency is set by the source; the wavelength shortens instead.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f56490e50b0e63', 'subj_phys', 'waves', 'Waves', 'Disturbances that carry energy through a medium or through space without carrying matter along.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0446e250e3077c', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0446e250e3077c', (SELECT id FROM formulas WHERE slug = 'wave-speed'), 1);

-- Lesson: reflection-mirrors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_312f98a6aa8f46', 'reflection-mirrors', 'Reflection and mirrors', 'Apply the law of reflection, describe plane-mirror images, and locate images in concave and convex mirrors with ray diagrams and the mirror equation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b9f7faeb8ab97d', 'les_312f98a6aa8f46', 1, 'State the law of reflection.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90df2f6e03491d', 'les_312f98a6aa8f46', 2, 'Describe images formed by plane, concave and convex mirrors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ce7ce348beae8', 'les_312f98a6aa8f46', 3, 'Use 1/f = 1/dₒ + 1/dᵢ and m = −dᵢ/dₒ for mirrors.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b9f7faeb8ab97d', 'les_312f98a6aa8f46', 'learn', 1, 'definition', '{"term":"Law of reflection","body":"The angle of reflection equals the angle of incidence, both measured from the normal. A plane mirror forms an upright, virtual image the same size as the object, as far behind the mirror as the object is in front."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90df2f6e03491d', 'les_312f98a6aa8f46', 'learn', 2, 'definition', '{"term":"Curved mirrors","body":"A concave mirror (focal length $f > 0$) can form real, inverted images (object beyond F) or virtual, upright, enlarged images (object inside F). A convex mirror ($f < 0$) always forms small, upright, virtual images."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ce7ce348beae8', 'les_312f98a6aa8f46', 'learn', 3, 'worked_example', '{"title":"An object 30 cm from a concave mirror with f = 10 cm","steps":[{"latex":"\\tfrac{1}{d_i} = \\tfrac{1}{10} - \\tfrac{1}{30} \\Rightarrow d_i = 15\\ \\text{cm}","explanation":"Real, in front of the mirror."},{"latex":"m = -\\tfrac{15}{30} = -0.5","explanation":"Inverted, half size."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6cc74202103cb9', 'les_312f98a6aa8f46', 'experiment', 4, 'activity', '{"activity":"ray-optics","title":"Move the object toward the mirror","params":{"optic":"concave","focal":10,"object":30}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bab26bc2ea09bd', 'les_312f98a6aa8f46', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Slide the object inside the focal point (below 10 cm): the image jumps behind the mirror, upright and enlarged, like a makeup mirror."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc69a2105cbfcb', 'les_312f98a6aa8f46', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car side mirrors are convex (wider view, objects closer than they appear); headlights and telescopes use concave mirrors."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b9f7faeb8ab97d', 'les_312f98a6aa8f46', 1, 'practice', 'numeric', 2, 'An object is 5 cm from a concave mirror with f = 10 cm. Find the image distance.', '{"answer":-10,"unit":"cm"}', '[]', '$\frac{1}{d_i} = \frac{1}{10} - \frac{1}{5} = -\frac{1}{10}$: virtual, behind the mirror.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90df2f6e03491d', 'les_312f98a6aa8f46', 2, 'practice', 'numeric', 2, 'Find the magnification for that image.', '{"answer":2}', '[]', '$-\frac{-10}{5} = 2$: upright, twice as tall.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ce7ce348beae8', 'les_312f98a6aa8f46', 3, 'practice', 'multiple_choice', 1, 'You stand 2 m in front of a plane mirror. How far are you from your image?', '{"choices":["2 m","4 m","1 m","0 m"],"answer":1}', '[]', 'The image is 2 m behind the mirror.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6cc74202103cb9', 'les_312f98a6aa8f46', 4, 'review', 'multiple_choice', 3, 'A store security mirror shows a wide, small, upright view. It is…', '{"choices":["plane","concave","convex","a lens"],"answer":2}', '[]', 'Convex mirrors always do this.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_428a27c98800ac', 'subj_phys', 'optics', 'Optics', 'How light reflects and refracts to form images with mirrors and lenses.');
