-- Lesson: sound-doppler
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f68f2b1d045994', 'sound-doppler', 'Sound and the Doppler effect', 'Relate pitch and loudness to frequency and intensity, use the decibel scale, and compute frequency shifts from moving sources and observers.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b94ec974376e96', 'les_f68f2b1d045994', 1, 'Connect pitch to frequency and loudness to intensity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_084b342cc2380d', 'les_f68f2b1d045994', 2, 'Use the decibel scale: +10 dB means 10 times the intensity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b558a509e17b76', 'les_f68f2b1d045994', 3, 'Apply the Doppler equation with correct signs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b94ec974376e96', 'les_f68f2b1d045994', 'learn', 1, 'definition', '{"term":"Sound","body":"Sound is a longitudinal pressure wave, about 343 m/s in air at 20 °C (faster in liquids and solids). Pitch depends on frequency; humans hear about 20 Hz to 20 kHz. Loudness depends on intensity; each +10 dB multiplies intensity by 10."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_084b342cc2380d', 'les_f68f2b1d045994', 'learn', 2, 'definition', '{"term":"Doppler effect","body":"$f'' = f\\,\\frac{v \\pm v_o}{v \\mp v_s}$. Use the top signs for motion toward each other (higher pitch) and the bottom signs for moving apart (lower pitch)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b558a509e17b76', 'les_f68f2b1d045994', 'learn', 3, 'worked_example', '{"title":"An ambulance siren (700 Hz) moves at 30 m/s","steps":[{"latex":"\\text{approaching: } 700\\cdot\\tfrac{343}{343 - 30} \\approx 767\\ \\text{Hz}","explanation":""},{"latex":"\\text{receding: } 700\\cdot\\tfrac{343}{343 + 30} \\approx 644\\ \\text{Hz}","explanation":"The familiar drop in pitch as it passes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1f00e613c6491', 'les_f68f2b1d045994', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Police radar, weather radar and Doppler ultrasound of blood flow all measure speed from frequency shifts; astronomers use the same idea with light (redshift)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b94ec974376e96', 'les_f68f2b1d045994', 1, 'practice', 'numeric', 2, 'A 500 Hz source approaches a still listener at 20 m/s (v = 343 m/s). What frequency is heard, to the nearest Hz?', '{"answer":531,"tolerance":1,"unit":"Hz"}', '[]', '$500 \cdot \frac{343}{323} \approx 531$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_084b342cc2380d', 'les_f68f2b1d045994', 2, 'practice', 'multiple_choice', 1, 'A sound goes from 60 dB to 80 dB. Its intensity becomes…', '{"choices":["2 times as large","20 times as large","100 times as large","1.33 times as large"],"answer":2}', '[]', '+20 dB: $10 \times 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b558a509e17b76', 'les_f68f2b1d045994', 3, 'practice', 'numeric', 2, 'Lightning is seen, and thunder heard 3 s later. How far away was it, in meters (343 m/s)?', '{"answer":1029,"tolerance":2,"unit":"m"}', '[]', '$343 \times 3$ (light''s travel time is negligible).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c1f00e613c6491', 'les_f68f2b1d045994', 4, 'review', 'multiple_choice', 3, 'A listener drives away from a stationary siren. The pitch they hear is…', '{"choices":["higher","lower","the same","zero"],"answer":1}', '[]', 'Moving apart lowers the frequency.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f56490e50b0e63', 'subj_phys', 'waves', 'Waves', 'Disturbances that carry energy through a medium or through space without carrying matter along.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f68f2b1d045994', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f68f2b1d045994', (SELECT id FROM formulas WHERE slug = 'wave-speed'), 1);

-- Lesson: standing-waves-resonance
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3b58a14fd0b4bc', 'standing-waves-resonance', 'Standing waves and resonance', 'Explain standing waves as interference of opposite-moving waves, find the harmonics of strings and open and closed pipes, and connect them to resonance.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a376ca4a1b3b4c', 'les_3b58a14fd0b4bc', 1, 'Describe superposition, nodes and antinodes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_81f450496a2c07', 'les_3b58a14fd0b4bc', 2, 'Find fₙ = nv/(2L) for strings and open pipes, and fₙ = nv/(4L) (odd n) for closed pipes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_790856214a3cfc', 'les_3b58a14fd0b4bc', 3, 'Explain resonance as driving a system at a natural frequency.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a376ca4a1b3b4c', 'les_3b58a14fd0b4bc', 'learn', 1, 'definition', '{"term":"Standing waves","body":"Two identical waves moving in opposite directions add to a standing wave with fixed nodes (no motion) and antinodes (maximum motion). On a string fixed at both ends: $\\lambda_n = \\frac{2L}{n}$ and $f_n = \\frac{nv}{2L}$, $n = 1, 2, 3, \\ldots$"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81f450496a2c07', 'les_3b58a14fd0b4bc', 'learn', 2, 'worked_example', '{"title":"A guitar string, L = 0.65 m, wave speed 286 m/s","steps":[{"latex":"f_1 = \\tfrac{286}{2(0.65)} = 220\\ \\text{Hz}","explanation":"The fundamental."},{"latex":"f_2 = 440\\ \\text{Hz}","explanation":"Second harmonic, an octave higher."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_790856214a3cfc', 'les_3b58a14fd0b4bc', 'learn', 3, 'definition', '{"term":"Pipes","body":"An open pipe behaves like a string: $f_n = \\frac{nv}{2L}$. A pipe closed at one end has only odd harmonics: $f_n = \\frac{nv}{4L}$, $n = 1, 3, 5, \\ldots$"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aeecdfd0481329', 'les_3b58a14fd0b4bc', 'experiment', 4, 'activity', '{"activity":"waves","title":"Harmonics on a string","params":{"mode":"standing","harmonic":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a339fbbd89383', 'les_3b58a14fd0b4bc', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch to Superposition and set the phase to 180°: the waves cancel (destructive interference). At 0° they double (constructive)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c52b8c9939ff3', 'les_3b58a14fd0b4bc', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Resonance makes instruments loud and can be destructive: soldiers break step on bridges, and engineers design buildings so earthquake frequencies don''t match their natural frequencies."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a376ca4a1b3b4c', 'les_3b58a14fd0b4bc', 1, 'practice', 'numeric', 1, 'Find the third harmonic of the guitar string above.', '{"answer":660,"unit":"Hz"}', '[]', '$3 \times 220$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81f450496a2c07', 'les_3b58a14fd0b4bc', 2, 'practice', 'numeric', 2, 'A 0.5 m pipe closed at one end ($v = 343$ m/s). Find its fundamental frequency, to one decimal place.', '{"answer":171.5,"tolerance":0.1,"unit":"Hz"}', '[]', '$\frac{343}{4(0.5)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_790856214a3cfc', 'les_3b58a14fd0b4bc', 3, 'practice', 'multiple_choice', 2, 'How many nodes does the 3rd harmonic on a string fixed at both ends have (counting the ends)?', '{"choices":["2","3","4","6"],"answer":2}', '[]', '$n + 1 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aeecdfd0481329', 'les_3b58a14fd0b4bc', 4, 'review', 'multiple_choice', 3, 'Tightening a guitar string raises its pitch because…', '{"choices":["the string gets longer","the wave speed increases","the wavelength increases","the amplitude increases"],"answer":1}', '[]', 'Higher tension, faster waves, higher $f = \frac{v}{2L}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f56490e50b0e63', 'subj_phys', 'waves', 'Waves', 'Disturbances that carry energy through a medium or through space without carrying matter along.');
